-- ----------------------------
-- Table structure for tool_prod_category
-- ----------------------------
DROP TABLE IF EXISTS `tool_prod_category`;
CREATE TABLE `tool_prod_category`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '分类名称',
  `parent_id` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT '父级ID，0表示顶级分类',
  `level` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '层级深度：1=一级，2=二级...',
  `path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '物化路径，格式如：/0/1/5/',
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT '排序权重，越小越靠前',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '菜单图标 URL 或类名',
  `is_visible` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否显示在菜单中：1=显示，0=隐藏',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_parent_id`(`parent_id`) USING BTREE,
  INDEX `idx_path`(`path`) USING BTREE,
  INDEX `idx_sort`(`sort_order`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_520_ci COMMENT = '产品工具分类表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tool_prod_category
-- ----------------------------

