-- ----------------------------
-- Table structure for user_platform_url_config
-- ----------------------------
DROP TABLE IF EXISTS `user_platform_url_config`;
CREATE TABLE `user_platform_url_config`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `platform_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '平台ID',
  `platform_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '平台名称',
  `url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '平台URL地址',
  `request_interval_ms` int(11) NOT NULL DEFAULT 1000 COMMENT '请求间隔毫秒数 (默认1秒)',
  `timeout_ms` int(11) NOT NULL DEFAULT 5000 COMMENT '单次请求超时时间毫秒数',
  `retry_count` tinyint(4) NOT NULL DEFAULT 3 COMMENT '失败重试次数',
  `pre_action_type` tinyint(4) NULL DEFAULT 0 COMMENT '前置操作类型 (0:无 1:登录 2:获取Token 3:执行JS)',
  `pre_action_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL COMMENT '前置操作详细配置 (JSON格式)',
  `headers_template` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL COMMENT '默认请求头模板 (JSON格式)',
  `concurrency_limit` int(11) NOT NULL DEFAULT 1 COMMENT '最大并发限制数',
  `request_params` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '请求参数',
  `parse_attr` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '解析属性',
  `sort` int(11) NULL DEFAULT NULL COMMENT '排序',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_platform_id`(`platform_id`) USING BTREE
